        IDictionary<string, object> options = this.safeDict(response, "nobitex", new Dictionary<string, object>() {});
        IDictionary<string, object> amountPrecisions = this.safeDict(options, "amountPrecisions", new Dictionary<string, object>() {});
        List<object> ids = new List<object>(((IDictionary<string,object>)amountPrecisions).Keys);
        IDictionary<string, object> pricePrecisions = this.safeDict(options, "pricePrecisions", new Dictionary<string, object>() {});
        IDictionary<string, object> minOrders = this.safeDict(options, "minOrders", new Dictionary<string, object>() {});
        IDictionary<string, object> quoteIds = this.safeDict(this.options, "quoteIds", new Dictionary<string, object>() {});
        List<object> suffixes = new List<object>(((IDictionary<string,object>)quoteIds).Keys);
        List<object> result = new List<object>() {};
        for (int i = 0; isLessThan(i, getArrayLength(ids)); postFixIncrement(ref i))
        {
