    public override Dictionary<string, object> parseOrder(object order, object market = null)
    {
        // "BTC-RLS" -> "BTCIRT", "BTC-USDT" -> "BTCUSDT"
        string? marketId = this.safeString(order, "market");
        if (isTrue(!isEqual(marketId, null)))
        {
            marketId = ((string)marketId).Replace((string)"-RLS", (string)"IRT");
            marketId = ((string)marketId).Replace((string)"-", (string)"");
        }
        market = this.safeMarket(marketId, market);
        string? execution = this.safeString(order, "execution"); // Limit, Market, StopLimit, StopMarket
        string? type = null;
        if (isTrue(!isEqual(execution, null)))
        {
            type = ((bool) isTrue(((string)execution).EndsWith(((string)"Market")))) ? "market" : "limit";
        }
        IDictionary<string, object> statuses = this.safeDict(this.options, "orderStatuses", new Dictionary<string, object>() {});
        string? average = this.safeString(order, "averagePrice");
        return this.safeOrder(new Dictionary<string, object>() {
            { "id", this.safeString(order, "id") },
            { "clientOrderId", this.safeString(order, "clientOrderId") },
            { "timestamp", this.parse8601(this.safeString(order, "created_at")) },
            { "datetime", null },
            { "lastTradeTimestamp", null },
            { "symbol", getValue(market, "symbol") },
            { "type", type },
            { "timeInForce", null },
            { "postOnly", null },
            { "side", this.safeString(order, "type") },
            { "price", this.safeString(order, "price") },
            { "triggerPrice", this.safeString(order, "param1") },
            { "amount", this.safeString(order, "amount") },
            { "filled", this.safeString(order, "matchedAmount") },
            { "remaining", this.safeString(order, "unmatchedAmount") },
            { "cost", this.safeString(order, "totalPrice") },
            { "average", ((bool) isTrue((isEqual(average, "0")))) ? null : average },
            { "status", this.safeString(statuses, this.safeString(order, "status")) },
            { "fee", new Dictionary<string, object>() {
                { "cost", this.safeString(order, "fee") },
                { "currency", null },
            } },
            { "trades", null },
            { "info", order },
        }, market);
    }

    public override object sign(object path, object api = null, object method = null, object parameters = null, object headers = null, object body = null)
    {
        api ??= "public";
        method ??= "GET";
        parameters ??= new Dictionary<string, object>();
        string fullPath = add("/", this.implodeParams(path, parameters));
        object query = this.omit(parameters, this.extractParams(path));
        headers = new Dictionary<string, object>() {};
        if (isTrue(isEqual(method, "POST")))
        {
            body = this.json(query);
            ((IDictionary<string,object>)headers)["Content-Type"] = "application/json";
        } else if (isTrue(isGreaterThan(getArrayLength(new List<object>(((IDictionary<string,object>)query).Keys)), 0)))
        {
            fullPath = add(fullPath, add("?", this.urlencode(query)));
        }
        if (isTrue(isEqual(api, "private")))
        {
            this.checkRequiredCredentials();
            if (isTrue(isTrue(!isEqual(this.secret, null)) && isTrue(!isEqual(this.secret, ""))))
            {
                // API Key auth: Ed25519 over timestamp + METHOD + full_path + raw_body, keys and signature are url-safe base64
                string timestamp = ((object)this.seconds()).ToString();
                object payload = add(add(timestamp, method), fullPath);
                if (isTrue(!isEqual(body, null)))
                {
                    payload = add(payload, body);
                }
                object secret = this.secret;
                secret = ((string)secret).Replace((string)"-", (string)"+");
                secret = ((string)secret).Replace((string)"_", (string)"/");
                object seed = this.arraySlice(this.base64ToBinary(secret), 0, 32);
                string signature = eddsa(this.encode(payload), seed, ed25519);
                signature = ((string)signature).Replace((string)"+", (string)"-");
                signature = ((string)signature).Replace((string)"/", (string)"_");
                ((IDictionary<string,object>)headers)["Nobitex-Key"] = this.apiKey;
                ((IDictionary<string,object>)headers)["Nobitex-Timestamp"] = timestamp;
                ((IDictionary<string,object>)headers)["Nobitex-Signature"] = signature;
            } else
            {
                // legacy session token
                ((IDictionary<string,object>)headers)["Authorization"] = add("Token ", this.apiKey);
            }
        }
        object url = add(getValue(getValue(this.urls, "api"), "rest"), fullPath);
        return new Dictionary<string, object>() {
            { "url", url },
            { "method", method },
            { "body", body },
            { "headers", headers },
        };
    }

    public override object handleErrors(object httpCode, object reason, object url, object method, object headers, object body, object response, object requestHeaders, object requestBody)
    {
        if (isTrue(isEqual(response, null)))
        {
            return null;
        }
        //
        //     { "status": "failed", "code": "InvalidSymbol", "message": "..." }
        //     { "detail": "توکن غیر مجاز" } // invalid token, http 401
        //
        if (isTrue(isTrue(isEqual(httpCode, 401)) || isTrue(isEqual(httpCode, 403))))
        {
            throw new AuthenticationError ((string)add(add(this.id, " "), body)) ;
        }
        string? status = this.safeString(response, "status");
        if (isTrue(isTrue(!isEqual(status, null)) && isTrue(!isEqual(status, "ok"))))
        {
            throw new ExchangeError ((string)add(add(this.id, " "), body)) ;
        }
        return null;
    }
